describe("upstream news-market golden fixtures", () => { for (const [i, f] of GOLD.entries())
    it(`${f.fn} ${i}`, () => { let got: any; const a = f.args, k = f.kwargs; if (f.fn === "assign_session")
        got = assignNewsSession(a[0], bars(a[1]), a[2] ?? k.now_utc);
    else if (f.fn === "measure_company")
        got = measureNewsCompany(a[0], bars(a[1]), bars(a[2]), a[3], a[4] ?? k.story_last_utc ?? null);
    else if (f.fn === "measure_country")
        got = measureNewsCountry(a[0], bars(a[1]), a[2], a[3] ?? k.story_last_utc ?? null);
    else if (f.fn === "classify_companies")
        got = classifyNewsCompanies(a[0], new Set(a[1] ?? k.categories ?? []), a[2] ?? k.feeds);
    else if (f.fn === "classify_countries")
        got = classifyNewsCountries(a[0], a[1] ?? k.excluded);
    else
        got = newsBenchmark(a[0]); expect(got).toEqual(f.expected); }); });
